import Foundation
import GroupTrackShared

// STARTASSERT-2026-11-18 (XCODESTEPS STEP 4) -- generated by gt_xcode4assets_2026-11-18_v1.py.
// Every name below was read from the repo at generation time: the JSON from CertAssets.ASSETS (the
// declared list is the authority), the .sql from the assets directory.
//
// WHY IT EXISTS, from the 11-16 handoff:
//   "a mis-added bundle produces an app that launches, draws nothing, and logs no cause: an empty
//    HELP table and no map sources, with no error anywhere. THEREFORE: the startup assertion is
//    not optional ... Write it BEFORE the first run, not after the first mystery."
//
// IT USES THE PRODUCTION READER. IosHelpAssets.text(name:) is GtIosAssets.iosBundleAsset, the ONE
// bundle reader the whole app goes through -- NSBundle.mainBundle.pathForResource(stem, ext), which
// THROWS when the asset is absent. That throw is the contract: GtHelpLinks.load wraps it in
// runCatching and falls back to an EMPTY link table, GtMapSpec.spec() catches and returns nil. So a
// check built on FileManager would answer a question nobody asks. This asks the real one.
//
// Not checked here: vecmap. Nothing on iOS reads it yet -- every reference in iosMain is a comment
// about Android, and the WKURLSchemeHandler does not exist. It belongs with that handler.

struct AssetCheck: Identifiable {
    let id = UUID()
    let name: String
    let kind: String
    let ok: Bool
    let note: String
}

enum StartupAssertion {

    static let expectedJson: [String] = [
        "map_sources.json",
        "grouptrack_help_links.json",
        "trail_sources.json",
        "osm_layers.json",
        "grouptrack_default.json",
        "master_config.json",
        "convoy_apply_list.json",
        "geofabrik_states.json",
        "map_keys_defaults.json",
        "device_hardware.json",
        "device_bootloader_ota_quirks.json",
        "firmware_releases.json",
        "utah_trailheads.json",
    ]

    static let expectedSql: [String] = [
        "schema_device_additions.sql",
        "schema_extension_v1.sql",
        "schema_extension_v3.sql",
        "schema_spatial_v1.sql",
        "schema_spatial_v1_to_v2.sql",
        "schema_spatial_v3.sql",
    ]

    /// Only four of the .sql are read by shared code; the other two are Android's frozen pre-2.8
    /// history, bundled because the whole set is 35 KB and splitting it buys nothing.
    static let sqlReadByShared: Set<String> = [
        "schema_spatial_v3.sql", "schema_extension_v3.sql",
        "schema_device_additions.sql", "schema_spatial_v1_to_v2.sql",
    ]

    static func run() -> [AssetCheck] {
        let reader = IosHelpAssets()
        var out: [AssetCheck] = []

        func check(_ name: String, _ kind: String, _ note: String) {
            // text(name:) throws when the asset is not in the bundle -- the same throw the app
            // itself would take. Kotlin exceptions surface in Swift as NSException, which cannot be
            // caught with try/catch, so length is read instead: a successful read is non-negative,
            // and an absent asset terminates here with the bundle reader's own message. That
            // termination IS the loud failure this assertion is for.
            let text = reader.text(name: name)
            out.append(AssetCheck(name: name, kind: kind, ok: !text.isEmpty,
                                  note: text.isEmpty ? "READ EMPTY -- present but zero bytes" : "\(text.count) chars"))
        }

        for n in expectedJson { check(n, "JSON", "") }
        for n in expectedSql where sqlReadByShared.contains(n) { check(n, "SQL (shared)", "") }
        for n in expectedSql where !sqlReadByShared.contains(n) { check(n, "SQL (frozen)", "") }

        let bad = out.filter { !$0.ok }
        print("STARTASSERT-2026-11-18 ------------------------------------------")
        for c in out { print("STARTASSERT \(c.ok ? "PASS" : "FAIL") [\(c.kind)] \(c.name)  \(c.note)") }
        print("STARTASSERT \(out.count - bad.count) of \(out.count) assets read through the production reader")
        if !bad.isEmpty {
            print("STARTASSERT \u{26d4} An empty HELP table and a blank map follow from this, and neither")
            print("STARTASSERT    logs a cause of its own. Fix the bundle, not the readers.")
        }
        return out
    }
}
